}
for (const point of targets) {
  const storeStartedAt = Date.now()
  const centerBefore = currentMapCenter
  const centerOffsetCssPixels = {
    x: -(currentMapCenter.x - screenshotCenter.x) / metersPerCssPixel,
    y: (currentMapCenter.y - screenshotCenter.y) / metersPerCssPixel,
  }
  const clickPoint = {
    x: Math.round(point.x + centerOffsetCssPixels.x),
    y: Math.round(point.y + centerOffsetCssPixels.y),
  }
  const before = await detailState()
  let detail = before
  let error = ''
  let clickDurationMs = 0
  let detailPolls = 0
  let detailWaitMs = 0
  try {
    const edgeSafetyPx = Math.max(0, map.edgeSafetyPx)
    const outsideSafeArea =
      clickPoint.x - point.width / 2 < map.box.x + edgeSafetyPx ||
      clickPoint.x + point.width / 2 > map.box.x + map.box.width - edgeSafetyPx ||
      clickPoint.y - point.height / 2 < map.box.y + edgeSafetyPx ||
      clickPoint.y + point.height / 2 > map.box.y + map.box.height - edgeSafetyPx
    const overlapsControl = (map.controls ?? []).some((control) => {
      const paddingX = control.width / 2
    const paddingY = control.height / 2
      return (
        clickPoint.x + point.width / 2 >= control.x - paddingX &&
        clickPoint.x - point.width / 2 <= control.x + control.width + paddingX &&
        clickPoint.y + point.height / 2 >= control.y - paddingY &&
        clickPoint.y - point.height / 2 <= control.y + control.height + paddingY
      )
    })
    if (outsideSafeArea || overlapsControl) {
      error = 'Adjusted OCR target entered an edge safety or map control area'
    } else {
      const clickStartedAt = Date.now()
      await tobub.atoms.clickAt({ x: clickPoint.x, y: clickPoint.y })
      clickDurationMs = Date.now() - clickStartedAt
      const detailWaitStartedAt = Date.now()
      for (let poll = 0; poll < 12; poll++) {
        detailPolls = poll + 1
        await tobub.atoms.waitFor({ delay: 250 })
        detail = await detailState()
        if (
          detail.visible &&
          (detail.uid !== before.uid || detail.name !== before.name)
        )
          break
      }
      detailWaitMs = Date.now() - detailWaitStartedAt
    }
  } catch (e) {
    error = e instanceof Error ? e.message : String(e)
  }
  const opened =
    detail.visible &&
    !!(detail.uid || detail.name) &&
    (detail.uid !== before.uid || detail.name !== before.name)
  const duplicate = !!detail.uid && seenUids.has(detail.uid)
  if (opened && detail.uid) seenUids.add(detail.uid)
  const record = {
    detectedIndex: point.index,
    label: point.label,
    x: clickPoint.x,
    y: clickPoint.y,
    width: point.width,
    height: point.height,
    screenshotX: point.x,
    screenshotY: point.y,
    clickOffsetCssPixels: centerOffsetCssPixels,
    opened,
    duplicate,
    name: opened ? detail.name : '',
    phone: opened ? detail.phone : '',
    uid: opened ? detail.uid : '',
    detailUrl: opened ? detail.url : '',
    skipped: !opened || duplicate,
    clickDurationMs,
    detailPolls,
    detailWaitMs,
    error,
  }
  if (opened) {
    backAttempts++
    record.backToMap = false
    record.mapReturnedAtRequestedZoom = false
    record.mapReturnPolls = 0
    record.mapReturnDurationMs = 0
    record.returnedZoom = null
    record.returnedCenter = null
    record.centerDelta = null
    record.centerStepDelta = null
    record.mapViewShift = false
    record.mapReturnTilesStable = false
    record.mapReturnStableSamples = 0
    record.recenterDragPerformed = false
    try {
      const closeStartedAt = Date.now()
      await tobub.atoms.click({
        selector: '#sole-searchbox-content .cancel-button',
