      let returnedCenter = null
      let previousReturnSignature = null
      let stableReturnSamples = 0
      for (let poll = 0; poll < 12; poll++) {
        if (poll > 0) await tobub.atoms.waitFor({ delay: 300 })
        restored = await mapState()
        returnedCenter = routeCenter(restored.url)
        record.mapReturnPolls++
        const readyMap =
          restored.ready &&
          !restored.url.includes('/poi/') &&
          !!returnedCenter &&
          restored.zoom === requestedZoom
        const tilesReady =
          restored.images > 0 && restored.loadedImages === restored.images
