      )
      record.centerAfterClose = returnedCenter
      if (record.backToMap && record.mapReturnTilesStable && returnedCenter) {
        const closeOffsetCssPixels = centerOffsetFor(returnedCenter)
        const restoreDrag = {
          x: Math.round(-closeOffsetCssPixels.x),
          y: Math.round(-closeOffsetCssPixels.y),
        }
