          x: returnedCenter.x - centerBefore.x,
          y: returnedCenter.y - centerBefore.y,
        }
        if (restoreDrag.x !== 0 || restoreDrag.y !== 0) {
          const inset = Math.max(0, map.edgeSafetyPx)
          const anchor = chooseDragAnchor(restored, returnedCenter)
          record.recenterAnchor = anchor
          const insideSafeMap = (point) =>
            point.x >= map.box.x + inset &&
            point.x <= map.box.x + map.box.width - inset &&
