            point.y <= map.box.y + map.box.height - inset
          const firstEndpoint = { x: anchor.x + restoreDrag.x, y: anchor.y + restoreDrag.y }
          if (!insideSafeMap(anchor) || !insideSafeMap(firstEndpoint)) {
            record.recenterError = 'One-step recenter drag would leave the safe map area'
          } else {
            await tobub.atoms.drag({
              from: anchor,
              to: firstEndpoint,
              steps: 1,
              easing: 'linear',
              stepPauseRange: [0, 0],
            })
            recenterDrags++
            record.recenterDragPerformed = true
            previousReturnSignature = null
            stableReturnSamples = 0
            for (let poll = 0; poll < 20; poll++) {
              if (poll > 0) await tobub.atoms.waitFor({ delay: 300 })
              restored = await mapState()
              returnedCenter = routeCenter(restored.url)
              record.mapReturnPolls++
              const readyMap =
                restored.ready &&
                !restored.url.includes('/poi/') &&
                !!returnedCenter &&
                restored.zoom === requestedZoom
              const tilesReady =
                restored.images > 0 && restored.loadedImages === restored.images
