                (scale) => Number.isFinite(scale) && scale > 0,
              )
              const sharedScale =
                validScales.length > 0
                  ? validScales.reduce((sum, scale) => sum + scale, 0) / validScales.length
                  : null
              if (!sharedScale) {
                let retryAnchor = null
                try {
                  retryAnchor = chooseDragAnchor(restored, returnedCenter, [anchor])
                } catch (anchorError) {
                  record.recenterError = String(anchorError)
                }
                if (retryAnchor) {
                  const retryEndpoint = {
                    x: retryAnchor.x + restoreDrag.x,
                    y: retryAnchor.y + restoreDrag.y,
