                    record.recenterError = 'Alternate recenter drag would leave the safe map area'
                  } else {
                    await tobub.atoms.drag({
                      from: retryAnchor,
                      to: retryEndpoint,
                      steps: 1,
                      easing: 'linear',
                      stepPauseRange: [0, 0],
                    })
                    recenterDrags++
