                    record.centerErrorAfterAnchorRetryCssPixels = retryOffset
                    record.recenterAnchorRetrySucceeded = !!(
                      stableReturnSamples >= 1 &&
                      retryOffset &&
                      Math.abs(retryOffset.x) <= centerRestoreToleranceCssPixels &&
                      Math.abs(retryOffset.y) <= centerRestoreToleranceCssPixels
                    )
                    record.recenterError = record.recenterAnchorRetrySucceeded
                      ? null
                      : 'Alternate recenter drag did not restore the map center within tolerance'
                  }
                }
              } else {
                const scaleX = measuredScale.x && measuredScale.x > 0 ? measuredScale.x : sharedScale
                const scaleY = measuredScale.y && measuredScale.y > 0 ? measuredScale.y : sharedScale
                const correction = {
                  x: Math.round(-firstDragOffset.x / scaleX),
                  y: Math.round(-firstDragOffset.y / scaleY),
                }
                record.recenterCorrectionScale = { x: scaleX, y: scaleY }
                record.recenterCorrectionDelta = correction
                const correctionAnchor = chooseDragAnchor(restored, returnedCenter)
                const correctionEndpoint = {
                  x: correctionAnchor.x + correction.x,
                  y: correctionAnchor.y + correction.y,
                }
                record.recenterCorrectionAnchor = correctionAnchor
                if (!insideSafeMap(correctionAnchor) || !insideSafeMap(correctionEndpoint)) {
                  record.recenterError = 'Measured center correction would leave the safe map area'
                } else if (correction.x === 0 && correction.y === 0) {
                  record.recenterError = 'Measured center correction rounded to no movement'
                } else {
                  await tobub.atoms.drag({
                    from: correctionAnchor,
                    to: correctionEndpoint,
                    steps: 1,
                    easing: 'linear',
                    stepPauseRange: [0, 0],
                  })
                  recenterDrags++
                  recenterCorrections++
                  record.recenterCorrectionPerformed = true
                  previousReturnSignature = null
                  stableReturnSamples = 0
                  for (let poll = 0; poll < 20; poll++) {
                    if (poll > 0) await tobub.atoms.waitFor({ delay: 300 })
                    restored = await mapState()
                    returnedCenter = routeCenter(restored.url)
                    record.mapReturnPolls++
                    const readyMap =
                      restored.ready &&
                      !restored.url.includes('/poi/') &&
                      !!returnedCenter &&
                      restored.zoom === requestedZoom
                    const tilesReady =
                      restored.images > 0 && restored.loadedImages === restored.images
                    if (!readyMap || !tilesReady) {
                      previousReturnSignature = null
                      stableReturnSamples = 0
                      continue
                    }
                    stableReturnSamples =
                      restored.signature === previousReturnSignature
                        ? stableReturnSamples + 1
                        : 0
                    previousReturnSignature = restored.signature
                    if (stableReturnSamples >= 1) break
                  }
                }
              }
            }
          }
        }
        const finalCenterOffset = returnedCenter
          ? {
              x: -(returnedCenter.x - screenshotCenter.x) / metersPerCssPixel,
              y: (returnedCenter.y - screenshotCenter.y) / metersPerCssPixel,
            }
          : null
        record.returnedCenter = returnedCenter
        record.centerAfterRestore = returnedCenter
        record.centerRestoreErrorCssPixels = finalCenterOffset
        record.mapReturnStableSamples = stableReturnSamples
        record.mapReturnTilesStable = !!(
          restored &&
          restored.ready &&
          !restored.url.includes('/poi/') &&
          restored.zoom === requestedZoom &&
          restored.images > 0 &&
          restored.loadedImages === restored.images &&
          stableReturnSamples >= 1
        )
        record.returnedZoom = restored?.zoom ?? null
        if (screenshotCenter && returnedCenter) {
          record.centerDelta = {
            x: returnedCenter.x - screenshotCenter.x,
            y: returnedCenter.y - screenshotCenter.y,
          }
        }
        record.mapReturnedAtRequestedZoom = !!(
          record.mapReturnTilesStable &&
          !!finalCenterOffset &&
          Math.abs(finalCenterOffset.x) <= centerRestoreToleranceCssPixels &&
          Math.abs(finalCenterOffset.y) <= centerRestoreToleranceCssPixels
        )
      }
      record.mapReturnDurationMs = Date.now() - closeStartedAt
      if (record.mapReturnedAtRequestedZoom && returnedCenter) {
        currentMapCenter = returnedCenter
        mapReturns++
      } else {
        backFailures++
        const reason = !record.backToMap
          ? 'Map did not return at the requested zoom within 12 polls'
          : !record.mapReturnTilesStable
            ? 'Map tiles did not stabilize after the one-step recenter'
            : record.recenterError || 'Map center did not return within the configured CSS pixel tolerance'
        record.error = (record.error ? record.error + '; ' : '') + reason
      }
    } catch (e) {
      record.error =
        (record.error ? record.error + '; ' : '') +
        'Return to map failed: ' +
        (e instanceof Error ? e.message : String(e))
      backFailures++
    }
  }
  record.storeElapsedMs = Date.now() - storeStartedAt
  if (record.opened && !record.duplicate) {
    const saved = await tobub.db.saveContent({
      platform: 'baidu',
      contentType: 'store',
      externalId:
        record.uid ||
        record.detailUrl ||
        `${latitude}:${longitude}:${record.detectedIndex}:${record.screenshotX}:${record.screenshotY}`,
      title: record.name || '百度地图店铺',
      summary: record.phone,
      url: record.detailUrl || screenshotMapUrl,
      tags: ['百度地图', '店铺'],
      metadata: {
        latitude,
        longitude,
        coordinateType: 'bd09ll',
        mapUrl: screenshotMapUrl,
        zoom: screenshotZoom,
      },
      rawData: record,
    })
    record.contentPersisted = true
    record.persistedContentId = saved.contentItemId ?? saved.id
  }
  records.push(record)
  await writer.append({ type: 'baidu-map-store-icon', payload: record })
  if (opened && (!record.backToMap || !record.mapReturnedAtRequestedZoom)) break
}
const collection = await writer.close()
const detectedCenters = located.objects.map((object, index) => {
  const bounds = object.bounds
  const valid =
    bounds &&
    [bounds.x, bounds.y, bounds.width, bounds.height].every(Number.isFinite) &&
    bounds.width > 0 &&
    bounds.height > 0
  return {
    index,
    x: valid ? (bounds.x + bounds.width / 2) * image.width : null,
    y: valid ? (bounds.y + bounds.height / 2) * image.height : null,
  }
})
const summary = {
  coordinate: { latitude, longitude, type: 'bd09ll' },
  mapUrl: screenshotMapUrl,
  requestedZoom,
  actualZoom: screenshotZoom,
  zoomClicks,
  zoomSteps,
  waitAfterZoomMs,
  stableRenderSamples,
  tileImages: { loaded: map.loadedImages, total: map.images },
  screenshot: {
    width: image.width,
    height: image.height,
    mapViewport: map.box,
  },
  detectedCenters,
  markerDomCount: map.markers,
  screenshotCount: 1,
  visionCalls,
  backAttempts,
  mapReturns,
  backFailures,
  recenterDrags,
  recenterCorrections,
  centerRestoreToleranceCssPixels,
  targetFiltering: targetFilterCounts,
  mapViewShifts: records.filter((r) => r.mapViewShift).length,
  recenteredDetails: records.filter((r) => r.mapReturnedAtRequestedZoom).length,
  edgeSafetyPx: map.edgeSafetyPx,
  coordinateOffsetMetersPerCssPixel: metersPerCssPixel,
  timings: {
    totalElapsedMs: Date.now() - executionStartedAt,
    clickMs: records.reduce((sum, r) => sum + (r.clickDurationMs || 0), 0),
    detailWaitMs: records.reduce((sum, r) => sum + (r.detailWaitMs || 0), 0),
    mapReturnMs: records.reduce((sum, r) => sum + (r.mapReturnDurationMs || 0), 0),
    mapReturnPolls: records.reduce((sum, r) => sum + (r.mapReturnPolls || 0), 0),
  },
  detectedIcons: located.objects.length,
  uniqueClickTargets: targets.length,
  clickAttempts: records.length,
  detailsOpened: records.filter((r) => r.opened).length,
  uniqueDetails: records.filter((r) => r.opened && !r.duplicate).length,
  persistedStores: records.filter((r) => r.contentPersisted).length,
  recordsWithPhone: records.filter((r) => r.opened && !r.duplicate && r.phone)
    .length,
  skipped: records.filter((r) => r.skipped).length,
  completeIconCoverageGuaranteed: false,
}
return { summary, records, collection }
